import React, { useState, useEffect, useRef } from 'react';
import { detectAdversarial, correctPrompt, queryLLM } from './services/api';
import ChatMessage from './components/ChatMessage';
import InputBar from './components/InputBar';


const App = () => {
  const [inputText, setInputText] = useState('');
  const [messages, setMessages] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const prompt = inputText.trim();
    setMessages(prev => [...prev, { sender: 'user', text: prompt }]);
    setInputText('');
    setIsLoading(true);

    try {
      const detectionResult = await detectAdversarial(prompt);
      if (detectionResult.isAdversarial) {
        setMessages(prev => [...prev, { sender: 'bot', text: 'Adversarial detected - correcting...' }]);
        const correctionResult = await correctPrompt(prompt);
        setMessages(prev => [...prev, { sender: 'bot', text: `Corrected Prompt: ${correctionResult.correctedPrompt}` }]);
        const llmResult = await queryLLM(correctionResult.correctedPrompt);
        setMessages(prev => [...prev, { sender: 'bot', text: llmResult.response }]);
      } else {
        const llmResult = await queryLLM(prompt);
        setMessages(prev => [...prev, { sender: 'bot', text: llmResult.response }]);
      }
    } catch (error) {
      setMessages(prev => [...prev, { sender: 'bot', text: 'Error processing your request.' }]);
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-4 font-sans">
      <h1 className="text-center text-xl font-semibold mb-4">Adversarial Chat Interface</h1>
      <div className="p-4 max-h-[60vh] overflow-y-auto border border-gray-300 rounded-lg mb-2 bg-white shadow-inner">
        {messages.map((msg, idx) => (
          <ChatMessage key={idx} sender={msg.sender} text={msg.text} />
        ))}
        <div ref={messagesEndRef} />
      </div>
      <InputBar
        value={inputText}
        onChange={(e) => setInputText(e.target.value)}
        onSubmit={handleSubmit}
        isLoading={isLoading}
      />
    </div>
  );
};

export default App;
